--[[
    WuKongHelper
        - WuKong的帮助类
        - 用于执行行动、查询、验证等操作
]]

local module = {}

local Container = require(game.ReplicatedStorage.Packages.WuKong.Types.Container)
local IHasPlugin = require(game.ReplicatedStorage.Packages.WuKong.Types.IHasPlugin)
local WuKongFacade = require(game.ReplicatedStorage.Packages.WuKong.WuKongFacade)

local Helper = _G.wdm.WuKong.Ioc.WuKongHelper

-- 获取Facade, 在客户端和服务端均可以调用
module.GetFacade = function(userId): WuKongFacade.Type
	local facade = nil
	local server = nil
	if game["Run Service"]:IsServer() then
		server = require(game.ReplicatedStorage.Packages.WuKong.WuKongServer)
	else
		facade = require(game.ReplicatedStorage.Packages.WuKong)
	end
	assert(userId)
	if game["Run Service"]:IsServer() then
		facade = server.GetFacade(userId)
	end
	return facade
end

-- 执行行动, location 为相对于传入容器的路径.
module.ExecuteAction = function(container: Container.Type, location: string, ...: any): any
	return Helper.ExecuteAction(container, location, ...)
end

-- 执行查询, location 为相对于传入容器的路径.
module.ExecuteQuery = function(container: Container.Type, location: string, ...: any): any
	return Helper.ExecuteQuery(container, location, ...)
end

-- 执行验证, location 为相对于传入容器的路径.
module.ExecuteValidator = function(container: Container.Type, location: string, ...: any): any
	return Helper.ExecuteValidator(container, location, ...)
end

-- 是否拥有指定名称的插件数据
module.HasPluginValue = function(pluginOwner: IHasPlugin.Type, key: string)
	return Helper.HasPluginValue(pluginOwner, key)
end

-- 尝试获取指定名称的插件数据
-- 返回: 是否拥有,插件数据
module.TryGetPluginValue = function(pluginOwner: IHasPlugin.Type, key: string)
	return Helper.TryGetPluginValue(pluginOwner, key)
end

-- 设置插件数据
module.SetPluginValue = function(pluginOwner: IHasPlugin.Type, key: string, value: any)
	return Helper.SetPluginValue(pluginOwner, key, value)
end

return module
